ht.test("Status is 200", function() {
    ht.expect(ht.response.status).toBe(200);
});

ht.test("Response time is acceptable", function() {
    ht.expect(ht.response.responseTime).toBeLessThan(5000);
});

var jsonData = ht.response.json();
ht.environment.set("responseBody", JSON.stringify(jsonData));

var data = ht.response.json();

ht.test("Has correct fields", function() {
    /* [Postman migration] .to.have.property("userId") has no ht equivalent */
    ht.expect(data.userId).toBeGreaterThan(0);
    /* [Postman migration] .to.be.a("string") has no ht equivalent */
    ht.expect(data.title).toContain(" ");
});

ht.test("Body is not empty", function() {
    ht.expect(ht.response.text()).toBeTruthy();
});

ht.test("ID matches", function() {
    ht.expect(data.id).toEqual(1);
});

ht.expect(ht.response.status).toBe(200);

/* [Postman migration] pm.collectionVariables is not supported */
/* [Postman migration] pm.globals is not supported */
/* [Postman migration] pm.execution.setNextRequest is not supported */

ht.test("This should still work", function() {
    ht.expect(ht.response.status).toBe(200);
});

var data = ht.response.json();
ht.environment.set("userId", data[0].userId);
ht.environment.set("postCount", data.length);

ht.test("Got multiple posts", function() {
    ht.expect(data.length).toBeGreaterThan(1);
});

ht.test("First post has title", function() {
    ht.expect(data[0].title).toBeTruthy();
    ht.expect(data[0].title).toContain(" ");
});
